import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))

import os, glob, re

# Search for JSONL files with "Demo" or test data
session_dir = os.environ.get('RLM_SESSION_DIR', '')
print("Session dir:", session_dir)

# Look for recent files
for root, dirs, files in os.walk(session_dir):
    for f in sorted(files):
        if f.endswith('.jsonl'):
            path = os.path.join(root, f)
            try:
                with open(path) as fp:
                    content = fp.read()[:2000]
                    if 'Demo' in content or 'Test' in content:
                        print(f"Found: {path}")
                        print("First 500 chars:", content[:500])
            except Exception as e:
                print(f"Error reading {path}: {e}")
